"kind": "propose",
"summary": "The renderer container's CPU limit is too low, causing throttling and liveness probe failures. Increasing the CPU limit to 1500m should alleviate the issue.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "The renderer container is consistently hitting its CPU limit (1 core), with 41% throttling and 93% usage, leading to liveness probe timeouts.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "No evidence of node-level CPU contention or recent rollout changes affecting CPU usage.",
    "supporting": ["ev-rollout_history"],
    "contradicting": ["ev-container_cpu"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise the CPU limit for the renderer container to 1500m, reducing throttling and allowing the liveness probes to succeed.",
  "rationale": "The renderer container is consistently hitting its CPU limit (1 core) with 41% throttling and 93% usage, leading to liveness probe timeouts. Raising the CPU limit to 1500m (1.5x current limit) should alleviate the throttling and allow the container to meet its CPU demands without being throttled.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
